import {api,escape as e} from './system.mjs';
const when=value=>new Date(value).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'});
export async function openLoyalty(customerId,{modal,detail,toast,quoteId=''}){
 const endpoint='/api/admin/customers/'+encodeURIComponent(customerId)+'/loyalty';
 let data=await api(endpoint),busy=false;
 const render=()=>{
  const card=data.cards.find(c=>c.status==='active'),points=card?.stamps.length||0;
  modal('<section class="ff-loyalty"><p class="ff-loyalty-eyebrow">FINE FORM · FIDELIDADE</p><h2>'+e(data.customer.name)+'</h2><p class="system-muted">'+e(data.customer.phone)+' · Controle exclusivo do painel</p><div role="status" class="ff-loyalty-feedback"></div>'+(card?'<article class="ff-loyalty-card"><header><span>SEU CUIDADO TEM RECOMPENSA</span><strong>'+points+' / '+card.target+'</strong></header><p class="ff-loyalty-reward">'+e(card.reward)+'</p><div class="ff-loyalty-circles" aria-label="Pontos do cartão">'+Array.from({length:card.target},(_,i)=>{const point=card.stamps[i];return '<button type="button" class="ff-loyalty-circle '+(point?'is-stamped':'')+'" '+(point||i!==points?'disabled':'data-loyalty-stamp')+' aria-label="'+(point?'Ponto '+(i+1)+' registrado no pedido '+e(point.reference):'Registrar ponto '+(i+1))+'" title="'+(point?e(point.reference)+' · '+e(when(point.created_at)):'Registrar serviço entregue')+'">'+(point?'✓':i+1)+'</button>';}).join('')+'</div><footer><span>Cartão '+e(card.id)+'</span><b>'+(points===card.target?'Prêmio disponível':(card.target-points)+' ponto(s) para seu prêmio')+'</b></footer></article>'+(points<card.target?'<label class="system-field"><span>Serviço entregue que vale este ponto</span><select id="loyalty-order" '+(!data.eligible.length?'disabled':'')+'>'+(!data.eligible.length?'<option>Nenhum pedido entregue disponível</option>':data.eligible.map(q=>'<option value="'+e(q.id)+'" '+(q.id===quoteId?'selected':'')+'>'+e(q.reference)+' · '+e(q.model)+'</option>').join(''))+'</select></label><p class="system-muted">Selecione o pedido e toque no próximo círculo branco. Ele ficará preto após a confirmação do sistema. Cada pedido vale um ponto, uma única vez.</p>':'<button type="button" class="button ff-loyalty-primary" data-loyalty-redeem>Confirmar entrega do prêmio ↗</button>'):'<div class="ff-loyalty-empty"><h3>Um novo motivo para voltar.</h3><p>Emita o cartão após o primeiro serviço entregue. Defina as regras antes de entregar o voucher físico.</p></div><form id="loyalty-issue"><label class="system-field"><span>Pontos para ganhar</span><input name="target" type="number" min="2" max="30" value="10" required></label><label class="system-field"><span>Prêmio deste cartão</span><input name="reward" maxlength="160" minlength="3" placeholder="Descreva o serviço ou benefício oferecido" required></label><button class="button ff-loyalty-primary" '+(!data.eligible.length?'disabled':'')+'>Emitir cartão</button>'+(!data.eligible.length?'<p class="system-muted">Conclua um novo pedido de serviço para emitir o cartão.</p>':'')+'</form>')+'<p class="ff-loyalty-rule">O voucher físico acompanha o cliente. A validade dos pontos e a entrega do prêmio são conferidas neste painel pelo número do cartão. Anote esse número no voucher.</p><details class="ff-loyalty-history"><summary>Histórico dos cartões ('+data.cards.length+')</summary>'+data.cards.map(c=>'<section><h3>'+e(c.reward)+' · '+(c.status==='redeemed'?'Prêmio entregue':'Em andamento')+'</h3><small>'+e(c.id)+'</small><ol>'+c.events.map(v=>'<li><strong>'+e({issued:'Cartão emitido',stamped:'Ponto registrado',redeemed:'Prêmio entregue'}[v.action])+'</strong> · '+e(v.detail)+'<small>'+e(when(v.created_at))+' · Operador '+e(v.actor_id)+'</small></li>').join('')+'</ol></section>').join('')+'</details></section>');
  detail.querySelector('#loyalty-issue')?.addEventListener('submit',event=>{event.preventDefault();const form=event.currentTarget;mutate({action:'issue',target:Number(form.elements.target.value),reward:form.elements.reward.value});});
  detail.querySelector('[data-loyalty-stamp]')?.addEventListener('click',()=>{const id=detail.querySelector('#loyalty-order')?.value;if(!data.eligible.some(q=>q.id===id)){toast('Nenhum pedido entregue disponível para pontuar.');return;}mutate({action:'stamp',cardId:card.id,version:card.version,quoteId:id});});
  detail.querySelector('[data-loyalty-redeem]')?.addEventListener('click',()=>{if(confirm('Confirma que entregou o prêmio “'+card.reward+'” a '+data.customer.name+'? Este resgate não pode ser repetido.'))mutate({action:'redeem',cardId:card.id,version:card.version,confirm:true});});
 };
 const mutate=async body=>{if(busy)return;busy=true;detail.querySelectorAll('.ff-loyalty button').forEach(b=>b.disabled=true);try{data=await api(endpoint,{method:'POST',body});render();toast(body.action==='stamp'?'Ponto registrado com segurança.':body.action==='issue'?'Cartão emitido. Toque no primeiro círculo para registrar o serviço.':'Prêmio entregue e registrado.');}catch(error){if(error.status===401)return;try{data=await api(endpoint);}catch(refreshError){if(refreshError.status===401)return;}render();const feedback=detail.querySelector('.ff-loyalty-feedback');feedback.textContent=error.message;feedback.classList.add('system-error');}finally{busy=false;}};
 render();
}
